<div class="toolbar"><p class="text-secondary mb-0"><?= number_format($result['total']) ?> registros · directorio de <?= e(mb_strtolower($m->meta['title'])) ?></p><div class="toolbar-actions"><a class="btn btn-outline-secondary" href="<?= e(url('catalog-export',['module'=>$m->module,'q'=>$_GET['q']??'','filter'=>$_GET['filter']??''])) ?>">↓ Exportar CSV</a><?php if(can_write()): ?><a class="btn btn-primary" href="<?= e(url('catalog-form',['module'=>$m->module])) ?>">+ Nuevo <?= e($m->meta['singular']) ?></a><?php endif ?></div></div>
<section class="panel"><form class="filter-bar" method="get"><input type="hidden" name="r" value="catalog"><input type="hidden" name="module" value="<?= e($m->module) ?>"><div class="search-field"><label class="visually-hidden" for="q">Buscar</label><input class="form-control" id="q" name="q" value="<?= e($_GET['q']??'') ?>" placeholder="Buscar en <?= e(mb_strtolower($m->meta['title'])) ?>…" maxlength="100"></div><?php if(isset($m->meta['filter'])): ?><label class="visually-hidden" for="filter">Filtrar</label><select class="form-select filter-select" name="filter" id="filter"><option value="">Todos los <?= $m->meta['filter']==='Country'?'países':'grupos' ?></option><?php foreach($options[$m->meta['filter']]??[] as $o): ?><option value="<?= e($o['id']) ?>" <?= (string)($_GET['filter']??'')===(string)$o['id']?'selected':'' ?>><?= e($o['label']) ?></option><?php endforeach ?></select><?php endif ?><button class="btn btn-primary">Buscar</button><a class="btn btn-light" href="<?= e(url('catalog',['module'=>$m->module])) ?>">Limpiar</a></form>
<div class="table-responsive"><table class="table align-middle"><thead><tr><?php foreach($m->meta['list'] as $col): ?><th><?= e($m->meta['fields'][$col]['label']??'Código') ?></th><?php endforeach ?><th class="text-end">Acciones</th></tr></thead><tbody><?php foreach($result['rows'] as $r): ?><tr><?php foreach($m->meta['list'] as $col): ?><td><?php if($col==='UnitPrice'): ?><?= money($r[$col]) ?><?php elseif($col==='Discontinued'): ?><span class="badge <?= (int)$r[$col]?'text-bg-secondary':'text-bg-success' ?>"><?= (int)$r[$col]?'Descontinuado':'Activo' ?></span><?php else: ?><?= e($r[$col]) ?><?php endif ?></td><?php endforeach ?><td class="text-end text-nowrap"><?php if(can_write()): ?><a class="btn btn-sm btn-light" href="<?= e(url('catalog-form',['module'=>$m->module,'id'=>$r[$m->meta['pk']]])) ?>">Editar</a><?php endif ?><?php if(is_admin()): ?><form class="d-inline" method="post" action="<?= e(url('catalog-delete',['module'=>$m->module])) ?>" data-confirm="¿Eliminar este registro? Las relaciones existentes impedirán la eliminación."><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($r[$m->meta['pk']]) ?>"><button class="btn btn-sm btn-outline-danger">Eliminar</button></form><?php endif ?><?php if(!can_write()): ?><span class="text-secondary small">Consulta</span><?php endif ?></td></tr><?php endforeach ?><?php if(!$result['rows']): ?><tr><td colspan="20" class="empty-state">No se encontraron resultados para los filtros seleccionados.</td></tr><?php endif ?></tbody></table></div>
